/* Creator Studio AI service worker. Generated by scripts/build-sw.mjs — edit the template. */
const VERSION = '__BUILD_ID__';
const SHELL = `shell-${VERSION}`;
const STATIC = `static-${VERSION}`;
const RUNTIME = `runtime-${VERSION}`;
const FFMPEG = 'ffmpeg-0.12.10'; // large runtime, kept across app updates
const ROUTES = ['/', '/create', '/projects', '/project', '/images', '/thumbnails', '/editor', '/seo', '/channels', '/settings'];
const ASSETS = ['/manifest.webmanifest', '/icons/icon-192.png', '/icons/icon-512.png', '/icons/apple-touch-icon.png', '/fonts/Montserrat-latin.woff2', '/fonts/Montserrat-latin-ext.woff2', '/fonts/Anton-latin.woff2', '/fonts/Anton-latin-ext.woff2', '/fonts/Cinzel.woff2'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(SHELL).then((cache) => Promise.allSettled([...ROUTES, ...ASSETS].map((u) => cache.add(new Request(u, { cache: 'reload' }))))),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keep = new Set([SHELL, STATIC, RUNTIME, FFMPEG]);
      for (const k of await caches.keys()) if (!keep.has(k)) await caches.delete(k);
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

async function cacheFirst(req, name) {
  const cache = await caches.open(name);
  const hit = await cache.match(req);
  if (hit) return hit;
  const res = await fetch(req);
  if (res.ok) cache.put(req, res.clone());
  return res;
}

async function networkFirstPage(req) {
  const cache = await caches.open(SHELL);
  try {
    const res = await fetch(req);
    if (res.ok) cache.put(new URL(req.url).pathname, res.clone());
    return res;
  } catch {
    const path = new URL(req.url).pathname;
    return (await cache.match(path)) || (await cache.match(req, { ignoreSearch: true })) || (await cache.match('/')) || new Response('Offline', { status: 503 });
  }
}

async function staleWhileRevalidate(req) {
  const cache = await caches.open(RUNTIME);
  const hit = await cache.match(req);
  const net = fetch(req)
    .then((res) => {
      if (res.ok) cache.put(req, res.clone());
      return res;
    })
    .catch(() => hit);
  return hit || net;
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;
  if (url.pathname.startsWith('/api/')) return; // AI calls are never cached
  if (req.mode === 'navigate') return event.respondWith(networkFirstPage(req));
  if (url.pathname.startsWith('/ffmpeg/')) return event.respondWith(cacheFirst(req, FFMPEG));
  if (url.pathname.startsWith('/_next/static/') || url.pathname.startsWith('/fonts/') || url.pathname.startsWith('/icons/')) return event.respondWith(cacheFirst(req, STATIC));
  if (url.searchParams.has('_rsc') || req.headers.get('RSC')) return event.respondWith(staleWhileRevalidate(req));
  event.respondWith(staleWhileRevalidate(req));
});
